public class BrightnessAdjusterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String colorAt(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "(null image)";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static String size(java.awt.image.BufferedImage img) {
        if (img == null) {
            return "(null image)";
        }
        return img.getWidth() + "x" + img.getHeight();
    }

    static java.awt.image.BufferedImage makeSource() {
        java.awt.image.BufferedImage src =
                new java.awt.image.BufferedImage(2, 2, java.awt.image.BufferedImage.TYPE_INT_RGB);
        src.setRGB(0, 0, 0xC86400);
        src.setRGB(1, 0, 0x0A141E);
        src.setRGB(0, 1, 0xFFFFFF);
        src.setRGB(1, 1, 0x000000);
        return src;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage src = makeSource();

            java.awt.image.BufferedImage up = BrightnessAdjuster.adjust(src, 60);
            check("adjust size", "2x2", size(up));
            check("+60 on (200,100,0) clamps red to 255", "#FFA03C", colorAt(up, 0, 0));
            check("+60 on (10,20,30)", "#46505A", colorAt(up, 1, 0));
            check("+60 on white stays white", "#FFFFFF", colorAt(up, 0, 1));

            java.awt.image.BufferedImage down = BrightnessAdjuster.adjust(src, -60);
            check("-60 on (200,100,0) clamps blue to 0", "#8C2800", colorAt(down, 0, 0));
            check("-60 on (10,20,30) clamps every channel to 0", "#000000", colorAt(down, 1, 0));
            check("-60 on white", "#C3C3C3", colorAt(down, 0, 1));

            java.awt.image.BufferedImage same = BrightnessAdjuster.adjust(src, 0);
            check("delta 0 copies the pixel", "#0A141E", colorAt(same, 1, 0));
            check("adjust returns a new image", true, same != null && same != src);
            check("src unchanged", "#C86400", colorAt(src, 0, 0));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

